use crate::{packet::{Context,Cover},core::Trace,linear,root};use hec_native_ic::fp::Fp;
pub fn build(context:&Context,tr:&Trace)->Cover{let f=Fp::new(context.ell);let z=root::power_map(&f,5).0;let mut roots:Vec<_>=(1..5).map(|e|f.pow(z,e)).collect();roots.sort();let n=tr.points.len()+1;let mut branches=vec![];for lambda in roots{let mut public=vec![0;n];public[0]=1;let mut rows=vec![(public,f.inv(context.sm))];let mut index=std::collections::BTreeMap::new();for(j,&(x,y))in tr.points.iter().enumerate(){let(mut xx,mut w)=(x,1);for _ in 0..5{assert!(index.insert((xx,y),(j,w)).is_none());let ny=context.c.fp.neg(y);if ny!=y{assert!(index.insert((xx,ny),(j,f.neg(w))).is_none());}xx=context.c.fp.mul(xx,tr.z);w=f.mul(w,lambda);}}for prim in &tr.primitives{let mut v=vec![0;n];v[n-1]=1;for xy in &prim.points{let &(j,w)=index.get(xy).unwrap();v[j]=f.add(v[j],w);}rows.push((v,f.neg(prim.a)));}let proof=linear::prove(&rows,n,&f);assert!(linear::verify(&rows,n,&f,&proof));branches.push((lambda,proof));}Cover{context:context.clone(),z:tr.z,reps:tr.points.clone(),primitives:tr.primitives.clone(),branches,k:tr.answer.unwrap().1,anchor_certificates:tr.anchor_certificates.clone()}}
